// Repositories/EmployeeRepository.cs
namespace PinkMachine19.TimeClock.Domain;

public sealed class EmployeeRepository
{
    private readonly Dictionary<int, Employee> _employees = new();
    private readonly HashSet<string> _employeeNames = new(StringComparer.OrdinalIgnoreCase);

    public bool TryAdd(Employee employee, out string message)
    {
        if (_employeeNames.Contains(employee.Name))
        {
            message = $"Employee name '{employee.Name}' already exists.";
            return false;
        }

        if (!_employees.TryAdd(employee.EmployeeId, employee))
        {
            message = $"Employee ID {employee.EmployeeId} already exists.";
            return false;
        }

        _employeeNames.Add(employee.Name);
        message = $"Added {employee.Name}.";
        return true;
    }

    public bool TryFind(int employeeId, out Employee? employee)
    {
        return _employees.TryGetValue(employeeId, out employee);
    }
}

// Add as a new Session 12 section at the end of App/Program.cs.
var employeeRepository = new EmployeeRepository();

var firstEmployee = new Employee(1, "Taylor", new Address { City = "Springfield" });
var duplicateId = new Employee(1, "Jordan", new Address { City = "Riverton" });
var duplicateName = new Employee(2, "taylor", new Address { City = "Lakeside" });

employeeRepository.TryAdd(firstEmployee, out string firstMessage);
Console.WriteLine(firstMessage);

employeeRepository.TryAdd(duplicateId, out string duplicateIdMessage);
Console.WriteLine(duplicateIdMessage);

employeeRepository.TryAdd(duplicateName, out string duplicateNameMessage);
Console.WriteLine(duplicateNameMessage);

if (employeeRepository.TryFind(1, out Employee? foundEmployee))
{
    Console.WriteLine($"Found: {foundEmployee.Name}");
}

bool foundMissing = employeeRepository.TryFind(999, out Employee? missingEmployee);
Console.WriteLine($"Missing employee found: {foundMissing}");
